static float NearestPacked(float value, unsigned fractionBits) {
    Require(std::isfinite(value) && value >= 0 && value <= (fractionBits == 6 ? 65024.f : 64512.f), "bounded packed rounding input");
    if (value == 0) return value;
    int exponent = 0;
    std::frexp(value, &exponent);
    const double step = std::ldexp(1.0, std::max(exponent - 1, -14) - static_cast<int>(fractionBits));
    return static_cast<float>(std::nearbyint(static_cast<double>(value) / step) * step);
}

static void Name(Texture& t, const char* name) {
    Util::SetResourceName(t.texture.Get(), "%s", name);
    Util::SetResourceName(t.srv.Get(), "%s SRV", name);
    Util::SetResourceName(t.uav.Get(), "%s UAV", name);
}
static Texture NamedTexture(ID3D11Device* d, const std::vector<Pixel>& p, const char* name) {
    auto t = MakeTexture(d, p); Name(t, name); return t;
}
static Texture PackedTexture(ID3D11Device* d, const char* name) {
    D3D11_TEXTURE2D_DESC desc{};
    desc.Width = desc.Height = 64; desc.MipLevels = desc.ArraySize = desc.SampleDesc.Count = 1;
    desc.Format = DXGI_FORMAT_R11G11B10_FLOAT; desc.Usage = D3D11_USAGE_DEFAULT;
    desc.BindFlags = D3D11_BIND_SHADER_RESOURCE | D3D11_BIND_UNORDERED_ACCESS;
    Texture t;
    Check(d->CreateTexture2D(&desc, nullptr, &t.texture));
    Util::SetResourceName(t.texture.Get(), "%s", name);
    Check(d->CreateShaderResourceView(t.texture.Get(), nullptr, &t.srv));
    Util::SetResourceName(t.srv.Get(), "%s SRV", name);
    Check(d->CreateUnorderedAccessView(t.texture.Get(), nullptr, &t.uav));
    Util::SetResourceName(t.uav.Get(), "%s UAV", name);
    return t;
}
static void Summary(const char* scene, const char* edit, const char* format,
                    const std::vector<Pixel>& b, const std::vector<Pixel>& r) {
    double rgb[3]{}, abs = 0, baseY = 0, maxAbs = 0;
    unsigned dark = 0, bright = 0, count = 0;
    for (unsigned y = 4; y < 60; ++y) for (unsigned x = 4; x < 60; ++x) {
        const auto i = y * 64 + x;
        const double bd[]{b[i].r, b[i].g, b[i].b}, rd[]{r[i].r, r[i].g, r[i].b};
        double dy = 0; const double weights[]{.2126,.7152,.0722};
        for (unsigned k = 0; k < 3; ++k) {
            Require(std::isfinite(rd[k]), "finite synthetic output");
            const double delta = rd[k] - bd[k]; rgb[k] += delta;
            abs += std::abs(delta) / 3; maxAbs = std::max(maxAbs, std::abs(delta));
            dy += weights[k] * delta; baseY += weights[k] * bd[k];
        }
        dark += dy < 0; bright += dy > 0; ++count;
    }
    const double dy = (rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722)/count;
    std::cout << scene << ',' << edit << ',' << format << ',' << count << ','
              << rgb[0]/count << ',' << rgb[1]/count << ',' << rgb[2]/count << ','
              << dy << ',' << 100*dy/(baseY/count) << ',' << abs/count << ','
              << maxAbs << ',' << dark << ',' << bright << '\n';
}
int main(int argc, char** argv) {
    Require(argc == 3, "provide production shader directory and copy shader");
    Require(std::fesetround(FE_TONEAREST) == 0, "nearest-even CPU rounding oracle");
    ComPtr<ID3D11Device> d; ComPtr<ID3D11DeviceContext> c;
    const D3D_FEATURE_LEVEL levels[]{D3D_FEATURE_LEVEL_11_0};
    Check(D3D11CreateDevice(nullptr,D3D_DRIVER_TYPE_WARP,nullptr,0,levels,1,
                           D3D11_SDK_VERSION,&d,nullptr,&c));
    auto reconstruct=Compile(d.Get(),std::filesystem::path(argv[1])/"ColorReconstructCS.hlsl");
    auto copy=Compile(d.Get(),std::filesystem::path(argv[2]));
    Util::SetResourceName(reconstruct.Get(),"NRBias::Reconstruct");
    Util::SetResourceName(copy.Get(),"NRBias::Copy");
    D3D11_BUFFER_DESC desc{}; desc.ByteWidth=sizeof(Constants);
    desc.Usage=D3D11_USAGE_DEFAULT; desc.BindFlags=D3D11_BIND_CONSTANT_BUFFER;
    ComPtr<ID3D11Buffer> cb; Check(d->CreateBuffer(&desc,nullptr,&cb));
    Util::SetResourceName(cb.Get(),"NRBias::Constants");
    Constants k; k.x=k.y=0; k.width=k.height=64; k.mode=2; k.domain=0;
    k.transform=0; k.bypass=0x100; k.detail=1; k.appearance=0; k.maximumStops=1;
    std::vector<Pixel> zeros(4096);
    auto decoded=NamedTexture(d.Get(),zeros,"NRBias::Decoded");
    std::cout << std::setprecision(12)
              << "scene,edit,format,samples,deltaR,deltaG,deltaB,deltaY,relativeYPercent,meanAbs,maxAbs,darkerPixels,brighterPixels\n";
    for (const char* scene:{"flat","ramp"}) {
        std::vector<Pixel> source(4096);
        for(unsigned y=0;y<64;++y)for(unsigned x=0;x<64;++x) {
            source[y*64+x] = std::string(scene)=="flat" ? Pixel{.15625f,.078125f,.0390625f,1} :
                Pixel{(64.f+x%32)/512.f,(64.f+y%32)/1024.f,(32.f+(x+y)%16)/1024.f,1};
        }
        auto input=NamedTexture(d.Get(),source,"NRBias::SourceInput");
        auto baseline=PackedTexture(d.Get(),"NRBias::Baseline");
        Dispatch(c.Get(),copy.Get(),cb.Get(),k,{input.srv.Get()},baseline.uav.Get());
        Dispatch(c.Get(),copy.Get(),cb.Get(),k,{baseline.srv.Get()},decoded.uav.Get());
        auto b=Read(d.Get(),c.Get(),decoded.texture.Get());
        for(const char* edit:{"identity","uniform_half","uniform_eighth_stop","tiny_checker","checker","hidden","zero_strength"}) {
            std::vector<Pixel> neural=b;
            for(unsigned y=0;y<64;++y)for(unsigned x=0;x<64;++x) {
                const std::string e(edit); float stops=0;
                if(e=="uniform_half")stops=-1;
                else if(e=="uniform_eighth_stop")stops=-.125f;
                else if(e=="tiny_checker")stops=((x+y)%2?1:-1)*.002f;
                else if(e=="checker"||e=="hidden"||e=="zero_strength")stops=((x+y)%2?1:-1)*.25f;
                auto& v=neural[y*64+x]; const float gain=std::exp2(stops);
                v.r*=gain;v.g*=gain;v.b*=gain;
            }
            auto ninput=NamedTexture(d.Get(),neural,"NRBias::NeuralInput");
            auto n=PackedTexture(d.Get(),"NRBias::Neural");
            Dispatch(c.Get(),copy.Get(),cb.Get(),k,{ninput.srv.Get()},n.uav.Get());
            for(const bool packed:{false,true}) {
                k.bypass=(packed?0x100:0)|(std::string(edit)=="hidden"?2:0);
                k.detail=std::string(edit)=="zero_strength"?0.f:1.f;
                auto result=packed?PackedTexture(d.Get(),"NRBias::ResultPacked"):
                                   NamedTexture(d.Get(),zeros,"NRBias::ResultFloat");
                Dispatch(c.Get(),reconstruct.Get(),cb.Get(),k,{baseline.srv.Get(),n.srv.Get(),baseline.srv.Get()},result.uav.Get());
                std::vector<Pixel> r;
                if(packed) {
                    Dispatch(c.Get(),copy.Get(),cb.Get(),k,{result.srv.Get()},decoded.uav.Get());
                    r=Read(d.Get(),c.Get(),decoded.texture.Get());
                } else r=Read(d.Get(),c.Get(),result.texture.Get());
                Summary(scene,edit,packed?"R11G11B10_FLOAT":"RGBA32_FLOAT",b,r);
                if (!packed) {
                    auto rounded = r;
                    for (auto& v : rounded) {
                        v.r = NearestPacked(v.r, 6); v.g = NearestPacked(v.g, 6); v.b = NearestPacked(v.b, 5);
                    }
                    auto q = NamedTexture(d.Get(), rounded, "NRBias::NearestOracleInput");
                    auto packedOracle = PackedTexture(d.Get(), "NRBias::NearestOraclePacked");
                    Dispatch(c.Get(),copy.Get(),cb.Get(),k,{q.srv.Get()},packedOracle.uav.Get());
                    Dispatch(c.Get(),copy.Get(),cb.Get(),k,{packedOracle.srv.Get()},decoded.uav.Get());
                    auto actual = Read(d.Get(),c.Get(),decoded.texture.Get());
                    for (unsigned i=0;i<4096;++i)
                        Require(actual[i].r==rounded[i].r&&actual[i].g==rounded[i].g&&actual[i].b==rounded[i].b,"nearest packed oracle round trip");
                    Summary(scene,edit,"R11G11B10_NEAREST_ORACLE",b,actual);
                }
                if(std::string(edit)=="identity"||std::string(edit)=="hidden"||std::string(edit)=="zero_strength")
                    for(unsigned i=0;i<4096;++i)Require(r[i].r==b[i].r&&r[i].g==b[i].g&&r[i].b==b[i].b,"endpoint exact");
            }
        }
    }
    c->ClearState(); c->Flush();
    return 0;
}

